// Criteria tests for #782 (quality gates in the build for new and
// changed code), step 5 of the proposal (issuecomment-7075114694),
// written before the implementation: "Prettier: config and check, the
// small sweep (styles, JSON, docs), then the scripts' sweep".
//
// The proposal's settings (section 1, "Formatter"): "Defaults, which
// match the house style: 80 columns, double quotes, semicolons, two
// spaces. It skips layouts/ (Go templates), content/ (shortcodes),
// recorded fixtures and generated files. ESLint's ten formatting rules
// go, since Prettier owns them ... max-len 80 stays ... that rule
// [camelcase] takes properties: "never" everywhere first". And section
// 2: "Every new gate goes inside npm run lint".
//
// Each test checks the gate, not the fix. Prettier is not installed
// on next, so nothing here imports it: the tests find the npm script
// that runs Prettier's check from `npm run lint`, run it, and read its
// exit and output. Its debug log names each file it reads and the
// options it loaded for it. Seeds are written beside the code for one
// run and removed after. Held out of runs as
// quality-prettier.criteria.mjs until the implementer renames it to
// quality-prettier.test.mjs.
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { existsSync, readFileSync, rmSync, statSync, writeFileSync }
  from "node:fs";
import { extname, isAbsolute, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { ESLint } from "eslint";

const root = resolve(fileURLToPath(new URL("..", import.meta.url)));
const tag = `zz-criteria-${process.pid}`;

// Prettier 3's defaults for the options a config can set. "Defaults"
// is the proposal's setting, so a config may name an option only to
// give it this value.
const PRETTIER_DEFAULTS = {
  "printWidth": 80,
  "tabWidth": 2,
  "useTabs": false,
  "semi": true,
  "singleQuote": false,
  "jsxSingleQuote": false,
  "quoteProps": "as-needed",
  "trailingComma": "all",
  "bracketSpacing": true,
  "objectWrap": "preserve",
  "bracketSameLine": false,
  "arrowParens": "always",
  "proseWrap": "preserve",
  "htmlWhitespaceSensitivity": "css",
  "endOfLine": "lf",
  "embeddedLanguageFormatting": "auto",
  "singleAttributePerLine": false,
  "experimentalTernaries": false,
  "experimentalOperatorPosition": "start",
};

// The ten rules in today's eslint.config.js that format code, each
// one eslint-config-prettier turns off: "ESLint's ten formatting rules
// go, since Prettier owns them".
const ESLINT_FORMATTING_RULES = [
  "array-bracket-spacing",
  "comma-dangle",
  "indent",
  "no-multi-spaces",
  "no-multiple-empty-lines",
  "no-tabs",
  "no-trailing-spaces",
  "quotes",
  "semi",
  "space-in-parens",
];

// One file of each kind the proposal names (scripts, stylesheets,
// JSON, YAML, Markdown), each one Prettier's defaults reformat, in a
// folder the check must read.
const FORMAT_SEEDS = {
  [`test/${tag}-format.mjs`]: "export const seeded = { a:1 };\n",
  [`assets/scripts/${tag}-format.js`]: "export const seeded = [1,2];\n",
  [`assets/styles/components/_${tag}-format.scss`]:
    ".zz-criteria-seed{color:red}\n",
  [`assets/styles/${tag}-format.css`]: ".zz-criteria-seed{color:red}\n",
  [`docs/${tag}-format.json`]: "{\"a\":1,  \"b\":2}\n",
  [`docs/${tag}-format.yml`]: "a:   1\n",
  [`docs/${tag}-format.md`]: "# Seed\n\n*  item\n",
};

const KINDS = /\.(js|mjs|cjs|scss|css|json|ya?ml|md)$/;

const tracked = () => execFileSync("git", ["ls-files", "-z"], {
  "cwd": root, "encoding": "utf8",
}).split("\0").filter((f) => f && existsSync(join(root, f)));

const head = (file, lines = 1) => {
  const abs = join(root, file);
  if (!statSync(abs).isFile()) return "";
  return readFileSync(abs, "utf8").split("\n", lines).join("\n");
};

const isNodeScript = (file) =>
  !extname(file) && /^#!.*\bnode\b/.test(head(file));

// What the proposal lets the check skip: Go templates, content with
// shortcodes, recorded fixtures, and generated files (npm's lock file,
// and the modules whose first line says "Generated by").
const skipped = (file) =>
  /^(layouts|content)\//.test(file) ||
  /(^|\/)fixtures\//.test(file) ||
  file === "package-lock.json" ||
  /^\/\/ Generated by /.test(head(file));

const kindFiles = () => tracked()
  .filter((f) => KINDS.test(f) || isNodeScript(f));

const seeds = [];
const seed = (path, text) => {
  const abs = join(root, path);
  writeFileSync(abs, text);
  seeds.push(abs);
  return abs;
};
const unseed = () => {
  for (const abs of seeds.splice(0)) rmSync(abs, { "force": true });
};
process.on("exit", unseed);

// Run an npm script the way the hook and CI do. The script shell is
// plain sh so a nested run is not recorded as one of the Mac's own.
const npm = (args) => spawnSync("npm", args, {
  "cwd": root,
  "encoding": "utf8",
  "env": { ...process.env, "npm_config_script_shell": "/bin/sh" },
  "maxBuffer": 64 * 1024 * 1024,
});

const ran = (result) =>
  `exit ${result.status}\n${result.stdout}\n${result.stderr}`.slice(-4000);

const scripts = () =>
  JSON.parse(readFileSync(join(root, "package.json"), "utf8")).scripts ??
  {};

// The scripts `npm run lint` runs: lint itself and every script it
// reaches through `npm run NAME`.
const reachedFromLint = () => {
  const all = scripts();
  const seen = new Set();
  const todo = ["lint"];
  while (todo.length) {
    const name = todo.pop();
    if (seen.has(name) || !(name in all)) continue;
    seen.add(name);
    const calls = all[name].matchAll(
      /npm\s+run(?:-script)?\s+(?:--?[\w-]+\s+)*([\w:.-]+)/g);
    for (const [, called] of calls) todo.push(called);
  }
  return seen;
};

const invokes = (command, bin) =>
  new RegExp(`(^|[\\s;&|(])(npx\\s+)?${bin}(\\s|$)`).test(command);

// The scripts lint reaches that run Prettier as a check, not a write.
const checkScripts = () => {
  const all = scripts();
  return [...reachedFromLint()].filter((name) =>
    invokes(all[name], "prettier") &&
    /(^|\s)(--check|-c|--list-different|-l)(\s|$)/.test(all[name]));
};

// Run every check script, with extra arguments appended to each.
const runChecks = (extra = []) => {
  const names = checkScripts();
  assert.ok(names.length > 0,
    "a script npm run lint reaches runs prettier --check");
  return names.map((name) => {
    const args = ["run", "--silent", name];
    if (extra.length) args.push("--", ...extra);
    return { name, "result": npm(args) };
  });
};

// Each file Prettier's debug log says it read, with the options it
// loaded for it: "resolve config from 'PATH'", then "loaded options
// `JSON`".
const readFiles = (output) => {
  const files = new Map();
  let current;
  for (const line of output.split("\n")) {
    const from = line.match(/resolve config from '(.+)'$/);
    if (from) {
      const abs = isAbsolute(from[1]) ? from[1] : resolve(root, from[1]);
      current = relative(root, abs);
      files.set(current, undefined);
      continue;
    }
    const loaded = line.match(/loaded options `(.*)`$/);
    if (loaded && current !== undefined) {
      files.set(current, JSON.parse(loaded[1]));
    }
  }
  return files;
};

const severity = (value) => {
  const level = Array.isArray(value) ? value[0] : value;
  return { "off": 0, "warn": 1, "error": 2 }[level] ?? level ?? 0;
};

const trackedScripts = () => tracked().filter((f) =>
  /\.(js|mjs|cjs)$/.test(f) || isNodeScript(f));

// For every tracked script, ESLint's resolved config; calls check with
// (file, rules) and collects what it returns, one line per miss.
const eachScriptConfig = async (check) => {
  const eslint = new ESLint({ "cwd": root });
  const misses = [];
  for (const file of trackedScripts()) {
    const config = await eslint.calculateConfigForFile(join(root, file));
    const miss = check(file, config?.rules ?? {});
    if (miss) misses.push(miss);
  }
  return misses;
};

describe("#782 step 5: Prettier's check", () => {
  let debugRuns;
  let read;

  before(() => {
    debugRuns = checkScripts().length
      ? runChecks(["--log-level", "debug"])
      : [];
    read = new Map();
    for (const { result } of debugRuns) {
      for (const [file, options] of
        readFiles(`${result.stdout}\n${result.stderr}`)) {
        read.set(file, options);
      }
    }
  });

  it("Prettier's check runs in npm run lint", () => {
    assert.notDeepEqual(checkScripts(), [],
      "no script that npm run lint reaches runs prettier --check");
  });

  it("Prettier's settings are its defaults, from a config", () => {
    assert.ok(read.size > 0, "the check's debug log names the files " +
      `it reads\n${debugRuns.map((r) => ran(r.result)).join("\n")}`);
    const noConfig = [...read].filter(([, o]) => o === null)
      .map(([f]) => f);
    assert.deepEqual(noConfig.slice(0, 20), [],
      `files Prettier reads with no config (${noConfig.length})`);
    const off = new Set();
    for (const options of read.values()) {
      for (const [key, value] of Object.entries(options ?? {})) {
        if (!(key in PRETTIER_DEFAULTS) ||
          PRETTIER_DEFAULTS[key] !== value) {
          off.add(`${key}: ${JSON.stringify(value)}`);
        }
      }
    }
    assert.deepEqual([...off], [], "options set to other than the default");
  });

  it("a seeded unformatted file of each kind fails the check", () => {
    for (const [path, text] of Object.entries(FORMAT_SEEDS)) {
      seed(path, text);
    }
    let runs;
    try {
      runs = runChecks();
    } finally {
      unseed();
    }
    const output = runs.map((r) => ran(r.result)).join("\n");
    assert.ok(runs.some((r) => r.result.status !== 0),
      `the check fails\n${output}`);
    const said = runs.map((r) => `${r.result.stdout}${r.result.stderr}`)
      .join("\n");
    const unnamed = Object.keys(FORMAT_SEEDS)
      .filter((path) => !said.includes(path));
    assert.deepEqual(unnamed, [],
      `seeded files the check does not report\n${output}`);
  });

  it("the check reads every tracked script, stylesheet, JSON, YAML " +
    "and Markdown file", () => {
    const missed = kindFiles().filter((f) => !skipped(f) && !read.has(f));
    assert.deepEqual(missed, [], "tracked files the check never reads");
  });

  it("the check skips templates, content, recorded fixtures and " +
    "generated files", () => {
    assert.ok(read.size > 0, "the check's debug log names the files " +
      "it reads");
    const formatted = [...read.keys()].filter((f) =>
      existsSync(join(root, f)) && skipped(f));
    assert.deepEqual(formatted, [],
      "files the proposal skips that the check reads");
  });
});

describe("#782 step 5: ESLint beside Prettier", () => {
  it("ESLint's ten formatting rules are off for every script",
    async () => {
      const misses = await eachScriptConfig((file, rules) => {
        const on = ESLINT_FORMATTING_RULES
          .filter((name) => severity(rules[name]) !== 0);
        return on.length ? `${file}: ${on.join(", ")}` : "";
      });
      assert.deepEqual(misses.slice(0, 20), [],
        `scripts where a formatting rule is on (${misses.length})`);
    });

  it("max-len stays an error at 80 columns for every script", async () => {
    const misses = await eachScriptConfig((file, rules) => {
      const value = rules["max-len"];
      const code = Array.isArray(value) ? value[1]?.code : undefined;
      return severity(value) === 2 && code === 80
        ? ""
        : `${file}: ${JSON.stringify(value)}`;
    });
    assert.deepEqual(misses.slice(0, 20), [],
      `scripts where max-len is not an error at 80 (${misses.length})`);
  });

  it("camelcase takes properties: never for every script", async () => {
    const misses = await eachScriptConfig((file, rules) => {
      const value = rules.camelcase;
      const options = Array.isArray(value) ? value[1] : undefined;
      return severity(value) === 2 && options?.properties === "never"
        ? ""
        : `${file}: ${JSON.stringify(value)}`;
    });
    assert.deepEqual(misses.slice(0, 20), [], "scripts where camelcase " +
      `is not an error with properties: never (${misses.length})`);
  });
});

after(unseed);
